import { add, emit, get, list, now, touch, integer, fail } from '../domain/core.mjs';
export const RATE_CARD = { version: 'demo-1', currency: 'DEMO', modelStep: 220, command: 80, delegation: 150, humanPerMinute: 120, synthetic: true };
export const rootRun = (s, run) => run.rootRunId ? get(s, 'runs', run.rootRunId) : run;
export function balance(s, run) { const root = rootRun(s, run); const spent = list(s, 'costs').filter(c => c.rootRunId === root.id).reduce((sum, c) => sum + c.amount, 0); const reserved = list(s, 'reservations').filter(c => c.rootRunId === root.id && c.status === 'Reserved').reduce((sum, c) => sum + c.amount, 0); return { budget: root.budget, spent, reserved, remaining: root.budget - spent - reserved, currency: 'DEMO', nextEstimate: RATE_CARD.modelStep + RATE_CARD.command, humanTimeMs: root.humanTimeMs || 0, rateCard: RATE_CARD.version }; }
export function cost(s, props, eventId) { const prior = list(s, 'costs').find(c => c.eventId === eventId && c.spaceId === props.spaceId); if (prior)
    return prior; integer(props.amount, 'amount', -10000000); const entry = add(s, 'costs', { ...props, eventId, currency: 'DEMO', rateCard: RATE_CARD.version, synthetic: true }); emit(s, 'cost.recorded', entry); return entry; }
export function reserve(s, run, amount, nodeId) { integer(amount); const root = rootRun(s, run); const b = balance(s, root); if (amount > b.remaining) {
    touch(s, run, { status: 'Blocked', reason: 'BudgetExceeded', recoveryActions: ['request-budget', 'cancel'] });
    if (!list(s, 'humanTasks').some(t => t.runId === root.id && t.kind === 'budget' && t.status === 'Pending')) {
        const space = get(s, 'spaces', run.spaceId);
        add(s, 'humanTasks', { spaceId: run.spaceId, projectId: run.projectId, runId: root.id, taskId: run.taskId, kind: 'budget', title: 'Требуется решение по бюджету', assigneeId: space.ownerId, role: 'po', status: 'Pending', balance: b, nextEstimate: amount });
        emit(s, 'budget.exceeded', run, 'system', { ...b, nextEstimate: amount });
    }
    return null;
} return add(s, 'reservations', { spaceId: run.spaceId, projectId: run.projectId, runId: run.id, rootRunId: root.id, nodeId, amount, status: 'Reserved' }); }
export function settle(s, reservation, eventId, amount = reservation.amount) { if (reservation.status === 'Settled')
    return; cost(s, { spaceId: reservation.spaceId, projectId: reservation.projectId, runId: reservation.runId, rootRunId: reservation.rootRunId, nodeId: reservation.nodeId, amount, category: 'execution', reservationId: reservation.id }, eventId); touch(s, reservation, { status: 'Settled' }); }
export function metrics(s, runs) { const started = runs.filter(r => !r.parentRunId); const count = status => started.filter(r => r.status === status).length; const accepted = count('Accepted'), failure = count('Failed'), cancelled = count('Cancelled'), pending = started.length - accepted - failure - cancelled; return { started: started.length, accepted, failure, cancelled, pending, acceptedRate: started.length ? accepted / started.length : null, withoutRework: started.filter(r => r.status === 'Accepted' && (r.reworks || 0) === 0 && (r.takeovers || 0) === 0).length, inputCount: started.reduce((x, r) => x + (r.inputCount || 0), 0), plannedApprovals: started.reduce((x, r) => x + (r.approvalCount || 0), 0), reworkCount: started.reduce((x, r) => x + (r.reworks || 0), 0), takeoverCount: started.reduce((x, r) => x + (r.takeovers || 0), 0), humanTimeMs: started.reduce((x, r) => x + (r.humanTimeMs || 0), 0), cost: started.reduce((x, r) => x + balance(s, r).spent, 0), blockedActions: s.events.filter(e => e.type === 'action.denied' && started.some(r => r.id === e.aggregateId)).length, prohibitedEffects: 0, maturity: pending ? 'preliminary' : 'complete', unit: 'started root run', synthetic: true }; }
